```cpp
struct Eertree { vector<array<int,26>> nx; vector<int> len, link, cnt; string s; int last = 1;
  Eertree() { nx.assign(2, {}); len = {-1, 0}; link = {0, 0}; cnt = {0, 0}; }
  int find(int v, int i) { while (i - len[v] - 1 < 0 || s[i - len[v] - 1] != s[i]) v = link[v]; return v; }
  void add(char ch) { s += ch; int i = s.size() - 1, c = ch - 'a', v = find(last, i);
    if (!nx[v][c]) { int u = len.size(); len.push_back(len[v] + 2); nx.push_back({}); cnt.push_back(0);
      link.push_back(len[u] == 1 ? 1 : nx[find(link[v], i)][c]); nx[v][c] = u; }
    last = nx[v][c]; ++cnt[last]; }
  // số palindrome khác nhau = len.size() - 2; số lần xuất hiện: cộng cnt theo link từ đỉnh dài về ngắn
};
```

