Mỗi cạnh tồn tại trên một khoảng thời gian [l, r): gắn nó vào O(log T) nút của segment tree theo thời gian; DFS cây, vào nút thì `unite` các cạnh của nút, ra thì rollback. DSU **không nén đường**, hợp theo kích thước, lưu stack thay đổi. O((m + q) log T log n).
```cpp
struct DSU { vector<int> p, sz; vector<pair<int,int>> st; DSU(int n): p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
  int find(int x) { while (p[x] != x) x = p[x]; return x; }
  void unite(int a, int b) { a = find(a); b = find(b); if (a == b) { st.push_back({-1, -1}); return; } if (sz[a] < sz[b]) swap(a, b); p[b] = a; sz[a] += sz[b]; st.push_back({a, b}); }
  void rollback() { auto [a, b] = st.back(); st.pop_back(); if (a < 0) return; p[b] = b; sz[a] -= sz[b]; } };
```

