```cpp
const int MOD = 998244353, G = 3;
long long pw(long long a, long long e) { long long r = 1; a %= MOD; for (; e; e >>= 1, a = a * a % MOD) if (e & 1) r = r * a % MOD; return r; }
void ntt(vector<long long>& a, bool inv) { int n = a.size();
  for (int i = 1, j = 0; i < n; ++i) { int bit = n >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) swap(a[i], a[j]); }
  for (int len = 2; len <= n; len <<= 1) { long long w = pw(G, (MOD - 1) / len); if (inv) w = pw(w, MOD - 2);
    for (int i = 0; i < n; i += len) { long long wn = 1;
      for (int j = 0; j < len / 2; ++j) { long long u = a[i + j], v = a[i + j + len / 2] * wn % MOD;
        a[i + j] = (u + v) % MOD; a[i + j + len / 2] = (u - v + MOD) % MOD; wn = wn * w % MOD; } } }
  if (inv) { long long ni = pw(n, MOD - 2); for (auto& x : a) x = x * ni % MOD; } }
vector<long long> multiply(vector<long long> a, vector<long long> b) { int need = a.size() + b.size() - 1, n = 1;
  while (n < need) n <<= 1; a.resize(n); b.resize(n); ntt(a, false); ntt(b, false);
  for (int i = 0; i < n; ++i) a[i] = a[i] * b[i] % MOD; ntt(a, true); a.resize(need); return a; }
```
