long long minCoins(const vector<int>& c, int S) { const long long INF = 1e18; vector<long long> dp(S + 1, INF); dp[0] = 0;
  for (int s = 1; s <= S; ++s) for (int x : c) if (x <= s && dp[s - x] + 1 < dp[s]) dp[s] = dp[s - x] + 1;
  return dp[S] >= INF ? -1 : dp[S]; }
// Số cách (không phân biệt thứ tự) — vòng mệnh giá ở ngoài
long long countWays(const vector<int>& c, int S, long long MOD) { vector<long long> dp(S + 1); dp[0] = 1;
  for (int x : c) for (int s = x; s <= S; ++s) dp[s] = (dp[s] + dp[s - x]) % MOD; return dp[S]; }
