```cpp
struct Fraction {
  long long num, den;
  Fraction(long long n = 0, long long d = 1) : num(n), den(d) { normalize(); }
  void normalize() { long long g = std::gcd(llabs(num), llabs(den)); if (g) { num /= g; den /= g; } if (den < 0) { num = -num; den = -den; } }
  Fraction operator+(const Fraction& o) const { return Fraction(num * o.den + o.num * den, den * o.den); }
  bool operator<(const Fraction& o) const { return (__int128)num * o.den < (__int128)o.num * den; }
};
std::ostream& operator<<(std::ostream& os, const Fraction& f) { return os << f.num << "/" << f.den; }
```
- Truyền object lớn bằng `const T&` để không sao chép; hàm không sửa dữ liệu thì đánh dấu `const`.
- Kế thừa + `virtual` cho đa hình; hàm huỷ của lớp cơ sở có hàm ảo phải là `virtual`.

```cpp
int n, cnt = 0; vector<int> cur; vector<char> used;
void permute() { if ((int)cur.size() == n) { ++cnt; return; }   // xử lý một hoán vị trong cur
  for (int v = 1; v <= n; ++v) if (!used[v]) { used[v] = 1; cur.push_back(v); permute(); cur.pop_back(); used[v] = 0; } }
int queens(int r, int N, int cols, int d1, int d2) { if (r == N) return 1; int res = 0;
  for (int c = 0; c < N; ++c) if (!(cols >> c & 1) && !(d1 >> (r + c) & 1) && !(d2 >> (r - c + N) & 1))
    res += queens(r + 1, N, cols | 1 << c, d1 | 1 << (r + c), d2 | 1 << (r - c + N));
  return res; }
```
- Mẫu chung: chọn → đệ quy → bỏ chọn. Cắt nhánh sớm (kiểm tra điều kiện trước khi đi sâu) quyết định tốc độ.
- Tập con của n phần tử: duyệt `mask` từ 0 đến 2^n − 1.

```cpp
void mergeSort(vector<int>& a, int l, int r, vector<int>& tmp) { if (r - l <= 1) return; int m = (l + r) / 2;
  mergeSort(a, l, m, tmp); mergeSort(a, m, r, tmp); int i = l, j = m, k = l;
  while (i < m || j < r) tmp[k++] = (j >= r || (i < m && a[i] <= a[j])) ? a[i++] : a[j++];
  for (int t = l; t < r; ++t) a[t] = tmp[t]; }   // [l, r), ổn định, O(n log n)
```
- Quick sort trung bình O(n log n) nhưng tệ nhất O(n²) (chọn chốt ngẫu nhiên để tránh). Counting sort O(n + K) khi giá trị nhỏ.
- Merge sort đếm được số nghịch thế: khi lấy từ nửa phải, cộng thêm `m − i`.
- Trong thi đấu dùng `std::sort` (introsort) / `std::stable_sort`; tự viết khi đề yêu cầu hoặc cần đếm nghịch thế.

